const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const user = await req({ method: 'GET', url: SB + '/auth/v1/user' });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto, zerar) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); const atual = zerar ? (r.progresso || []).filter(p => p.tipo !== 'busca') : (r.progresso || []); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...atual, { em: new Date().toISOString(), texto, tipo: 'busca' }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { } };

try {
  const [av] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=id,endereco,condominio,bairro,cidade,uf,cep,tipo_imovel,area_base_calculo_m2,area_privativa_m2,dormitorios,vagas,ano_construcao,dados_confirmados_em,fontes_dados' });
  if (!av) throw new Error('Avaliação não encontrada ou sem acesso.');
  if (!av.dados_confirmados_em) throw new Error('Confira os dados do imóvel antes de buscar amostras.');
  if (!av.cidade || !av.area_base_calculo_m2 || av.area_base_calculo_m2 <= 1) throw new Error('Faltam cidade ou área do imóvel. Complete na aba Informações.');
  await patch({ etapa: 'buscando_amostras', etapa_erro: null, descartes: [] });
  await progresso('Começamos: vamos procurar imóveis à venda parecidos e próximos do avaliado.', true);
  let bairro = av.bairro;
  if (!bairro && av.cep) {
    try {
      const c = await this.helpers.httpRequest({ method: 'GET', url: 'https://viacep.com.br/ws/' + String(av.cep).replace(/[^0-9]/g, '') + '/json/', json: true, timeout: 8000 });
      if (c && c.bairro) { bairro = c.bairro; await patch({ bairro }); }
    } catch (e) { }
  }
  const ruaNome = String(av.endereco || '').split(',')[0].replace(/^\s*(rua|r\.|avenida|av\.?|alameda|al\.|travessa|tv\.|estrada|rodovia|praça|praca)\s+/i, '').trim();
  if (!bairro && ruaNome.length >= 3 && av.uf && av.cidade) {
    try {
      const lista = await this.helpers.httpRequest({ method: 'GET', url: 'https://viacep.com.br/ws/' + encodeURIComponent(av.uf) + '/' + encodeURIComponent(av.cidade) + '/' + encodeURIComponent(ruaNome) + '/json/', json: true, timeout: 8000 });
      const bairros = [...new Set((Array.isArray(lista) ? lista : []).map(x => x.bairro).filter(Boolean))];
      if (bairros.length === 1) { bairro = bairros[0]; await patch({ bairro }); }
    } catch (e) { }
  }
  const loc = (av.fontes_dados || {}).localizacao || null;
  const alvo = { endereco: av.endereco, condominio: av.condominio, bairro, cidade: av.cidade, uf: av.uf, cep: av.cep, tipo: av.tipo_imovel || 'imóvel', area_m2: av.area_base_calculo_m2, dormitorios: av.dormitorios, vagas: av.vagas, ano_construcao: av.ano_construcao, lat: loc && loc.lat, lng: loc && loc.lng };
  const tol = Number(P.area_tolerancia_pct) / 100;
  const aMin = Math.floor(alvo.area_m2 * (1 - tol)), aMax = Math.ceil(alvo.area_m2 * (1 + tol));
  const qTol = Number(P.quartos_tolerancia);
  const temQuartos = alvo.dormitorios > 0;
  const quartos = temQuartos ? Array.from({ length: qTol * 2 + 1 }, (_, i) => alvo.dormitorios - qTol + i).filter(q => q >= 1) : [];
  const item = { type: 'object', additionalProperties: false,
    required: ['url', 'portal', 'titulo', 'endereco', 'condominio', 'preco', 'area_m2', 'dormitorios', 'vagas', 'ano_construcao', 'data_anuncio', 'mesmo_condominio', 'mesma_rua', 'mesmo_bairro', 'negocio', 'lancamento'],
    properties: { url: { type: 'string' }, portal: { type: 'string' }, titulo: { type: 'string' }, endereco: { type: 'string' }, condominio: { type: 'string' }, preco: { type: 'number' }, area_m2: { type: 'number' },
      dormitorios: { type: 'integer' }, vagas: { type: 'integer' }, ano_construcao: { type: 'integer' }, data_anuncio: { type: 'string' }, mesmo_condominio: { type: 'boolean' }, mesma_rua: { type: 'boolean' }, mesmo_bairro: { type: 'boolean' },
      negocio: { type: 'string', enum: ['venda', 'aluguel', 'desconhecido'] }, lancamento: { type: 'boolean' } } };
  const schema = { type: 'object', additionalProperties: false, required: ['anuncios'], properties: { anuncios: { type: 'array', items: item } } };
  const ehTerreno = /terreno|lote/i.test(String(alvo.tipo));
  const t = ehTerreno ? 'terreno lote' : String(alvo.tipo || 'imóvel').replace(/_/g, ' ');
  const rua = String(alvo.endereco || '').split(',')[0].trim();
  const numAlvo = ((String(alvo.endereco || '').split(',')[1] || '').match(/\d+/) || [''])[0];
  const cid = alvo.cidade + ' ' + (alvo.uf || '');
  const dorm = !ehTerreno && temQuartos ? alvo.dormitorios + ' quartos ' : '';
  const faixa = aMin + ' a ' + aMax + ' m²';
  const ondeBairro = alvo.bairro || ('região da ' + rua);
  const sistema = 'Você pesquisa anúncios de imóveis para um laudo de avaliação judicial (método comparativo direto, ABNT NBR 14653). ' +
    'Imóvel avaliado: ' + JSON.stringify({ ...alvo, lat: undefined, lng: undefined }) + '. ' +
    (ehTerreno ? 'O imóvel avaliado é um TERRENO/LOTE: liste somente terrenos e lotes (nunca casas, apartamentos ou galpões). ' : '') +
    'Liste SOMENTE anúncios de VENDA ATIVOS (ainda no ar) de imóveis usados muito parecidos e PRÓXIMOS do avaliado: mesmo tipo, área entre ' + faixa +
    (temQuartos && !ehTerreno ? ', de ' + Math.min(...quartos) + ' a ' + Math.max(...quartos) + ' quartos' : '') +
    '. Prioridade máxima: o mesmo prédio/condomínio; depois a mesma rua; depois ruas a poucas quadras. Evite imóveis longe do endereço, mesmo no mesmo bairro. Prefira anúncios recentes. Descarte o que estiver fora dessas faixas e anúncios marcados como vendidos ou indisponíveis. ' +
    'Ignore aluguel e leilão; marque lancamento=true se for lançamento ou na planta. ' +
    'Para cada anúncio devolva a URL exata da página do anúncio (nunca página de busca, listagem ou de condomínio), o endereço com rua e número quando aparecer, o nome do condomínio/edifício se aparecer, ' +
    'o preço e a área em m² exatamente como aparecem na página, quartos e vagas (use -1 em vagas se não souber), o ano de construção se a página informar (0 se não souber) ' +
    'e data_anuncio = data de publicação ou última atualização do anúncio no formato AAAA-MM-DD se a página mostrar (texto vazio se não mostrar). ' +
    'Quando não souber preço ou área use 0. Não invente. Traga até ' + P.web_anuncios_por_pesquisa + ' anúncios.';
  const rodadas = [
    { foco: 'mesmo_predio', q: t + ' à venda ' + (alvo.condominio ? alvo.condominio + ' ' : '') + rua + (numAlvo ? ' ' + numAlvo : '') + ' ' + cid },
    { foco: 'mesma_rua', q: t + ' ' + dorm + 'à venda ' + rua + ' ' + ondeBairro + ' ' + cid },
    { foco: 'bairro', q: t + ' ' + dorm + 'à venda ' + ondeBairro + ' ' + cid + ' ' + faixa },
    { foco: 'portais', q: t + ' ' + dorm + 'venda ' + rua + ' ' + ondeBairro + ' ' + cid + ' ' + faixa + ' olx chavesnamao imovelweb lopes' },
  ];
  const slug = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const tn = slug(alvo.tipo);
  const vrTipo = /sobrado/.test(tn) ? 'sobrado_residencial' : /casa/.test(tn) ? 'casa_residencial' : /apart/.test(tn) ? 'apartamento_residencial' : /terreno|lote/.test(tn) ? 'lote-terreno_residencial' : /sala|comercial/.test(tn) ? 'sala_comercial' : /galp/.test(tn) ? 'galpao_comercial' : '';
  const qaTipo = /casa|sobrado/.test(tn) ? 'casa' : /apart/.test(tn) ? 'apartamento' : '';
  const ufS = String(alvo.uf || '').toLowerCase(), cidS = slug(alvo.cidade), baiS = slug(alvo.bairro);
  // São Paulo capital: o VivaReal exige a zona no caminho (senão o robô trava). Zona pelo começo do CEP.
  const cep2 = String(alvo.cep || '').replace(/[^0-9]/g, '').slice(0, 2);
  const zona = cidS === 'sao-paulo' && ufS === 'sp' ? ({ '01': 'centro', '02': 'zona-norte', '03': 'zona-leste', '04': 'zona-sul', '05': 'zona-oeste', '08': 'zona-leste' })[cep2] || '' : '';
  const portais = String(P.portais || '').split(',').map(s => s.trim()).filter(Boolean);
  const runs = [];
  const base = { business: 'sale', maxItemsPerPortal: Number(P.anuncios_por_portal), maxItems: Number(P.anuncios_por_portal), convertToUsd: false };
  if (portais.includes('vivareal') && (zona || cidS !== 'sao-paulo')) {
    const qs = '?areaMinima=' + aMin + '&areaMaxima=' + aMax + (quartos.length && !ehTerreno ? '&quartos=' + quartos.join(',') : '');
    const caminho = zona ? zona + '/' + (baiS ? baiS + '/' : '') : (baiS ? 'bairros/' + baiS + '/' : '');
    runs.push({ portal: 'vivareal', apify: { ...base, portals: ['vivareal'], startUrls: [{ url: 'https://www.vivareal.com.br/venda/' + ufS + '/' + cidS + '/' + caminho + (vrTipo ? vrTipo + '/' : '') + qs }] } });
  }
  if (portais.includes('quintoandar') && qaTipo) {
    runs.push({ portal: 'quintoandar', apify: { ...base, portals: ['quintoandar'], startUrls: [{ url: 'https://www.quintoandar.com.br/comprar/imovel/' + (baiS ? baiS + '-' : '') + cidS + '-' + ufS + '-brasil/' + qaTipo + '/de-' + aMin + '-a-' + aMax + '-m2' + (quartos.length ? '/' + quartos.join('-') + '-quartos' : '') }] } });
  }
  await progresso('Pesquisando na internet ' + t + ' de ' + faixa + (temQuartos && !ehTerreno ? ', ' + Math.min(...quartos) + ' a ' + Math.max(...quartos) + ' quartos' : '') + ', no mesmo prédio, na mesma rua e em ' + ondeBairro + '…');
  return rodadas.map(r => ({ json: { alvo, runs, foco: r.foco, consulta: r.q, req: { model: P.modelo_ia, temperature: 0, usage: { include: true }, plugins: [ { id: 'web', max_results: 20 } ],
    response_format: { type: 'json_schema', json_schema: { name: 'anuncios', strict: true, schema } },
    messages: [ { role: 'system', content: sistema }, { role: 'user', content: r.q } ] } } }));
} catch (e) {
  await patch({ etapa: 'erro', etapa_erro: String(e.message || e).slice(0, 300) }).catch(() => {});
  throw e;
}

const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const P = $('Parâmetros da busca').first().json;
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
if (!jwt || !/^[0-9a-f-]{36}$/i.test(String(avaliacaoId || ''))) throw new Error('Pedido inválido.');
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...(r.progresso || []), { em: new Date().toISOString(), texto, tipo: 'busca' }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { } };

try {
  const alvo = $('Preparar busca').first().json.alvo;
  const normE = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9 ,]/g, ' ').replace(/\s+/g, ' ').trim();
  // Coordenadas do Google para cada endereço.
  const chaves = $('Endereços para o mapa').all().map(i => i.json.chave);
  const geo = {};
  $input.all().forEach((it, i) => { const r = ((it.json || {}).results || [])[0]; if (r && chaves[i]) geo[chaves[i]] = { lat: r.geometry.location.lat, lng: r.geometry.location.lng, tipo: r.geometry.location_type, parcial: !!r.partial_match }; });
  const ptAlvo = alvo.lat && alvo.lng ? { lat: alvo.lat, lng: alvo.lng } : geo.ALVO || null;
  const rad = (x) => x * Math.PI / 180;
  const km = (a, b) => { const R = 6371, dLa = rad(b.lat - a.lat), dLo = rad(b.lng - a.lng); const h = Math.sin(dLa / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLo / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
  const distDe = (endereco) => { if (!ptAlvo) return null; const g = geo[normE(endereco)]; if (!g || g.tipo === 'APPROXIMATE') return null; return Math.round(km(ptAlvo, g) * 1000) / 1000; };

  // 1) Junta as rodadas da busca na web (IA) e o resultado dos portais (Apify).
  let lista = [], custoBusca = 0, rodadasOk = 0;
  const cits = {};
  for (const it of $('IA pesquisa anúncios na web').all()) {
    const r = it.json;
    try { const l = JSON.parse(r.choices[0].message.content).anuncios || []; lista = lista.concat(l.map(x => ({ ...x, origem: 'web' }))); rodadasOk++; } catch (e) { continue; }
    custoBusca += (r.usage && r.usage.cost) || 0;
    for (const a of (r.choices[0].message.annotations || [])) { const c = a.url_citation; if (c && c.url) { const k = c.url.split('?')[0].split('#')[0]; cits[k] = (cits[k] || '') + ' ' + String(c.content || '') + ' ' + String(c.title || ''); } }
  }
  let itensAp = [];
  const portaisResp = [];
  for (const it of $('Apify busca nos portais').all()) {
    let b = it.json.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
    if (Array.isArray(b)) { itensAp = itensAp.concat(b); portaisResp.push(b.length); } else portaisResp.push('falhou');
  }
  custoBusca += itensAp.length * 0.002;
  for (const p of itensAp) {
    if (!p || !p.url) continue;
    const dataP = p.published_at || p.listed_at || p.listedAt || p.created_at || p.createdAt || p.updated_at || p.updatedAt || '';
    const end = p.street ? [p.street, p.street_number].filter(Boolean).join(', ') + (p.neighborhood ? ', ' + p.neighborhood : '') : '';
    lista.push({ url: p.url, portal: p.portal || '', titulo: p.title || '', endereco: end, condominio: '', preco: Number(p.price) || 0, area_m2: Number(p.area_m2) || 0, dormitorios: Number(p.bedrooms) || 0, vagas: p.parking_spots === null || p.parking_spots === undefined ? -1 : Number(p.parking_spots), ano_construcao: 0, data_anuncio: String(dataP || ''), mesmo_condominio: false, mesma_rua: false, mesmo_bairro: false, negocio: p.business === 'sale' ? 'venda' : p.business === 'rent' ? 'aluguel' : 'desconhecido', lancamento: !!p.is_new_development, origem: 'portais', imagem: p.image || null, bairro_portal: p.neighborhood || '' });
  }
  if (!rodadasOk && !itensAp.length) throw new Error('A busca de anúncios falhou (web e portais). Tente de novo.');
  await progresso('Os portais trouxeram ' + itensAp.length + ' anúncios. Agora estamos medindo a distância de cada um até o imóvel, conferindo se ainda estão no ar e comparando…');

  const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  const nucleo = (s, palavras) => norm(s).split(' ').filter(w => w.length > 1 && !palavras.includes(w)).join(' ');
  const condoAlvo = nucleo(alvo.condominio, ['condominio', 'residencial', 'edificio', 'ed', 'cond', 'conjunto', 'res', 'do', 'da', 'de', 'e']);
  const ruaAlvo = nucleo(String(alvo.endereco || '').split(',')[0], ['rua', 'r', 'avenida', 'av', 'alameda', 'al', 'travessa', 'tv', 'estrada', 'praca', 'rodovia', 'do', 'da', 'de', 'dos', 'das']);
  const numAlvo = ((String(alvo.endereco || '').split(',')[1] || '').match(/\d+/) || [''])[0];
  const bairroAlvo = norm(alvo.bairro);
  const PRINCIPAIS = ['zapimoveis', 'vivareal', 'quintoandar', 'olx', 'imovelweb', 'chavesnamao'];
  const dominio = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };
  const principal = (h) => PRINCIPAIS.some(p => h.includes(p));
  const qTol = Number(P.quartos_tolerancia);
  const minimo = Number(P.minimo_amostras) || 3;
  const raio = Number(P.raio_max_km) || 1.5;
  const hoje = Date.now();
  const diasDe = (s) => { const m = String(s || '').match(/(\d{4})-(\d{2})-(\d{2})/); if (!m) return null; const t = Date.UTC(+m[1], +m[2] - 1, +m[3]); return t > hoje + 86400000 ? null : Math.max(0, Math.round((hoje - t) / 86400000)); };
  const fmtDist = (d) => d === null ? '' : d < 1 ? Math.round(d * 1000) + ' m' : d.toFixed(1).replace('.', ',') + ' km';

  // 2) Triagem em código: todo descarte fica registrado com o motivo.
  const descartes = [];
  const descartar = (a, u, motivo) => descartes.push({ url: u || a.url || null, portal: dominio(u || a.url || '') || a.portal || null, titulo: String(a.titulo || '').slice(0, 160), endereco: a.endereco || null, preco: a.preco || null, area_m2: a.area_m2 || null, motivo });
  const vistos = new Set();
  const base = [];
  for (const a of lista) {
    const u = String(a.url || '').split('?')[0].split('#')[0];
    if (!u.startsWith('http')) { descartar(a, u, 'Sem link do anúncio'); continue; }
    if (vistos.has(u)) continue; vistos.add(u);
    if (a.negocio !== 'venda') { descartar(a, u, a.negocio === 'aluguel' ? 'Aluguel' : 'Não é venda'); continue; }
    if (a.lancamento) { descartar(a, u, 'Lançamento ou na planta'); continue; }
    if (!(a.preco > 0)) { descartar(a, u, 'Sem preço no anúncio'); continue; }
    if (!(a.area_m2 > 0)) { descartar(a, u, 'Sem área no anúncio'); continue; }
    if (alvo.dormitorios > 0 && a.dormitorios > 0 && Math.abs(a.dormitorios - alvo.dormitorios) > qTol) { descartar(a, u, 'Quartos diferentes (' + a.dormitorios + '; avaliado tem ' + alvo.dormitorios + ')'); continue; }
    const host = dominio(u);
    const texto = a.origem === 'portais' ? [a.titulo, a.endereco, a.bairro_portal].join(' ') : (cits[u] || '');
    const tudo = norm([a.titulo, a.endereco, a.condominio, texto].join(' '));
    const condoOk = condoAlvo.length >= 4 && tudo.includes(condoAlvo);
    const ruaOk = ruaAlvo.length >= 4 && tudo.includes(ruaAlvo);
    const predioOk = ruaOk && numAlvo && new RegExp(ruaAlvo.replace(/[.*+?^${}()|[\]\\]/g, '') + ' (n |no |numero )?' + numAlvo + '( |$)').test(tudo);
    const bairroOk = a.mesmo_bairro || (bairroAlvo.length >= 3 && tudo.includes(bairroAlvo));
    const dist = a.endereco ? distDe(a.endereco) : null;
    if (dist !== null && dist > raio && !condoOk && !predioOk) { descartar(a, u, 'Longe do imóvel (' + fmtDist(dist) + '; máximo ' + fmtDist(raio) + ')'); continue; }
    const anel = condoOk || predioOk ? 1 : ruaOk ? 2 : bairroOk ? 3 : 4;
    const notas = [];
    if (dist !== null) notas.push('a ' + fmtDist(dist) + ' do imóvel');
    base.push({ ...a, url: u, portal: host || a.portal, principal: principal(host), anel, dist, nota_anel: notas.join('; '), texto, dias: diasDe(a.data_anuncio) });
  }
  let tol = Number(P.area_tolerancia_pct) / 100;
  const naFaixa = (a, t) => Math.abs(a.area_m2 - alvo.area_m2) <= alvo.area_m2 * t;
  let validos = base.filter(a => naFaixa(a, tol));
  let ampliou = false;
